def overlap_minutes(meetings: list[list[int]], k: int) -> int:
    if len(meetings) < k:
        return 0

    events: dict[int, int] = {}
    for start, end in meetings:
        if start < end:
            events[start] = events.get(start, 0) + 1
            events[end] = events.get(end, 0) - 1

    if not events:
        return 0

    total = 0
    active = 0
    prev_t = 0
    for t in sorted(events):
        if active >= k:
            total += t - prev_t
        active += events[t]
        prev_t = t

    return total
